export const SIMULINK_STD_LIB_WASM_BASE64 =
  "";

let cachedWasmBytes: Uint8Array | undefined;

/**
 * Decodes the pre-bundled `@modelscript/simulink-std-lib` `runtime.wasm` binary in Node.js, Browsers, or Web Workers.
 */
export function getSimulinkStdLibWasmBytes(): Uint8Array {
  if (!cachedWasmBytes) {
    cachedWasmBytes = decodeBase64Wasm(SIMULINK_STD_LIB_WASM_BASE64);
  }
  return cachedWasmBytes;
}
